select id, session_id, event_type, page, duration_sec, sum(duration_sec) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as running_duration_sec, ntile(5) over (partition by session_id order by duration_sec, id) as duration_sec_bucket, ntile(10) over (partition by page order by duration_sec desc, id) as duration_sec_bucket_2, row_number() over (partition by page, session_id order by event_time, id) as row_seq, first_value(duration_sec, true) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as first_known_duration_sec from web_events
